#!/usr/bin/env python3
"""
MyApp - A simple Python application with JSON structured logging.
Logs JSON-formatted events to stdout.
"""

import argparse
import json
import logging
import sys
import time
from datetime import datetime, timezone

# Parse command line arguments
parser = argparse.ArgumentParser(description='MyApp - JSON structured logging application')
parser.add_argument('--log-level', type=str, default='INFO',
                    choices=['INFO', 'WARN', 'ERROR'],
                    help='Logging level: INFO, WARN, or ERROR')
args = parser.parse_args()

# Map log level strings to logging module constants
level_map = {
    'INFO': logging.INFO,
    'WARN': logging.WARNING,
    'ERROR': logging.ERROR
}

log_level = level_map.get(args.log_level, logging.INFO)

# Configure logging to output JSON to stdout
class JSONFormatter(logging.Formatter):
    """Custom formatter that outputs JSON log records."""

    def format(self, record):
        log_entry = {
            "timestamp": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
            "level": record.levelname,
            "message": record.getMessage(),
            "service": "myapp"
        }
        return json.dumps(log_entry)

# Set up logging
logging.basicConfig(
    level=log_level,
    format='%(message)s',  # JSON formatter will override this
    handlers=[
        logging.StreamHandler(sys.stdout)
    ]
)

# Replace the formatter with our JSON formatter
for handler in logging.getLogger().handlers:
    if isinstance(handler, logging.StreamHandler):
        handler.setFormatter(JSONFormatter())

logger = logging.getLogger('myapp')

def main():
    """Main loop - log events at regular intervals."""
    logger.info("Service started")

    # Log events at regular intervals
    while True:
        try:
            # Log different events based on level
            if log_level <= logging.INFO:
                logger.info("Health check - service running normally")
            if log_level <= logging.WARN:
                logger.warning("Service running with warnings")
            if log_level <= logging.ERROR:
                logger.error("An error occurred in the service")

            time.sleep(5)  # Log every 5 seconds

        except Exception as e:
            logger.error(f"Unexpected error: {str(e)}")
            time.sleep(5)

if __name__ == '__main__':
    main()
EOF
